  // be_askUserQuestion
  "be_askUserQuestion.toolDescription": "Ask the user 1–4 related questions grouped into a single card and wait for answers. Once the user answers all questions and confirms on the final review page, all responses are returned at once. Each question offers 1–3 specific choices (≤ 20 chars per item), with labels unique after trimming. When the answer cannot be enumerated, set allowFreeText=true so the card draws a text field; never encode that as a choice labelled '입력' / '직접 입력' / '기타' / 'Other' — such a label is dropped and converted to allowFreeText automatically. Only assign a recommendedIndex for the choice with clear contextual weight (0 or 1 total). Other suggestions go in altIndices (0–N items) — the UI automatically attaches 'Recommend' / 'Alt' badges to the chips. If the answer is private or external user information (location, preference, etc.), leave both recommendedIndex and altIndices empty. Setting allowMultiple=true lets the user select multiple choices simultaneously; responses come back as answers[].choices: string[] (default false — single select, answers[].choice: string). summaryHint is the row label on the confirm step (≤ 10 chars). If not confirmed within 5 minutes, returns dismissed=true.",
  "be_askUserQuestion.questionsDesc": "1–{max} questions to ask the user together in a single card. The user answers them one by one via pagination and submits all at once on the final confirm page.",
  "be_askUserQuestion.questionItemDesc": "The question text shown to the user (one or two lines).",
  "be_askUserQuestion.choicesDesc": "Answer choices shown as buttons. Provide 1–3. Each must fit the chip: at most 40 display columns, i.e. about 40 Latin characters or 20 CJK ones. If there are more than 3 candidates, provide the 3 most useful choices for this decision. Static fallbacks ('Yes'/'No'/'Not sure') are prohibited — provide specific choices appropriate to the context of that branch. A choice is a button, so a label naming the act of typing ('입력', '직접 입력', '기타', 'Other', 'Custom') is not a choice: use allowFreeText for that. The field is required; empty labels and labels duplicated after trimming are rejected. Leave the array empty only together with allowFreeText=true.",
  "be_askUserQuestion.recommendedIndexDesc": "Index of the choice the model most recommends (0–2, since choices has at most 3 items). Only assign when one answer has clear contextual weight — 0 or 1 items total. Leave empty if the answer is private or external user information (location, preference, etc.). Values outside the choices array length are ignored at runtime.",
  "be_askUserQuestion.altIndicesDesc": "Array of indices for secondary recommended choices (0–N, up to choices length). The UI automatically attaches a gray 'Alt' badge to those chips. Values that duplicate recommendedIndex or fall outside choices length are ignored at runtime.",
  "be_askUserQuestion.allowMultipleDesc": "Multi-select mode allowing multiple choices to be selected at once. Default false (single select). When true, responses come as answers[].choices: string[] (array of selected labels); when false, answers[].choice: string. Use only for questions where multiple candidates can be correct simultaneously (interests, tags, ranges, etc.). Keep false for single-answer questions.",
  "be_askUserQuestion.allowFreeTextDesc": "Draws a text field as the last answer row so the user can type an answer the choices cannot express. Default false. The typed text comes back in its own field, answers[].freeText: string, never mixed into choice/choices. Use it for open values (a number, a name, a sentence) and combine it with choices when the common answers are known but the list is not exhaustive.",
  "be_askUserQuestion.placeholderDesc": "Placeholder shown inside the free-text field (≤ 40 chars). Only read when allowFreeText is true.",
  "be_askUserQuestion.summaryHintDesc": "Row label shown next to the answer on the confirm step of a multi-question card (≤ 10 chars). Example: 'Direction', 'Target'. If omitted, the question itself is truncated for use.",

  // be_askUserQuestionGate
