  "permissionsTab.osSandboxToggleError": "Error changing the OS tool sandbox setting: {message}",
  "permissionsTab.osSandboxWindowsConsentHeading": "Windows OS isolation needs repair",
  "permissionsTab.osSandboxWindowsConsentBody": "The Windows OS sandbox is normally provisioned when Ave is installed, so it is ready at first launch. It is not ready on this machine. Run administrator setup again to repair it. Permission repair may ask for administrator approval again. No Windows sign-out is required. Filesystem and network confinement activate after the app restarts once setup is ready.",
  "permissionsTab.osSandboxWindowsInstallButton": "Re-provision",
  "permissionsTab.osSandboxWindowsInstalling": "Re-provisioning…",
  "permissionsTab.osSandboxWindowsInstallCancelled": "Administrator permission was not granted (the Windows prompt was dismissed or could not be shown), so setup was cancelled. Check the sandbox status in this panel before re-provisioning.",
  "permissionsTab.osSandboxWindowsInstallError": "Windows sandbox setup error: {message}",
  "permissionsTab.osSandboxWindowsInstallPending": "Checking the current setup first, which can take up to about 45 seconds. If setup is needed, Windows then asks for administrator permission: approve it to continue. The prompt cannot appear while the screen is locked. The installer and its administrator prompt share a 2-minute limit. Later status checks and permission repair can take longer and may show another administrator prompt.",
  "permissionsTab.osSandboxWindowsInstallRefreshing": "Confirming the result. This can take up to about 45 seconds.",
  "permissionsTab.osSandboxWindowsInstallReady": "Windows OS isolation is set up and verified. Restart Ave to confine tools with it.",
  "permissionsTab.osSandboxWindowsInstallAlreadyReady": "Windows OS isolation is already set up and verified, so no administrator prompt was needed.",
  "permissionsTab.osSandboxWindowsInstallUnverified": "Setup ran, but Ave could not confirm sandbox readiness (sandbox user: {userState}, network filters: {wfpState}). This result does not prove OS isolation. Restart Ave and check again; if it persists, re-provision.",
  "permissionsTab.osSandboxWindowsInstallTimedOut": "The installer did not finish within 2 minutes, so Ave could not confirm the result. Some setup steps may have completed. Check again and re-provision when you can approve the administrator prompt.",
  "permissionsTab.osSandboxWindowsInstallUnexpected": "Windows sandbox setup returned a result Ave does not recognize, so the setup result is unconfirmed. Check the sandbox status in this panel before re-provisioning or restarting Ave.",
  "permissionsTab.osSandboxWindowsInstallRejected": "Ave did not receive the Windows sandbox setup result. Setup may have started or completed. Check the sandbox status in this panel before trying again.",
  "permissionsTab.osSandboxWindowsStatusRefreshFailed": "Ave could not re-read the Windows sandbox status after setup. Restart Ave to see the current state.",
  "permissionsTab.osSandboxWindowsInstallFailedWfp": "Windows could not install the network filters the sandbox needs. Sandbox readiness is unconfirmed. Check that the Windows \"Base Filtering Engine\" service is running and that no security software blocks firewall changes, then re-provision.",
  "permissionsTab.osSandboxWindowsInstallFailedUser": "Windows could not create or configure the local sandbox user account. Sandbox readiness is unconfirmed. A policy on this PC may block creating local accounts; ask your administrator, then re-provision.",
  "permissionsTab.osSandboxWindowsInstallFailedConfigConflict": "Windows sandbox network filters with different settings already exist on this PC. Ave does not replace them automatically; the setup result is unconfirmed. Ask your administrator to inspect the conflicting filters before re-provisioning.",
  "permissionsTab.osSandboxWindowsInstallFailedAmbient": "Windows did not accept the write protection on its shared system folders, so file confinement would be incomplete and Ave did not accept the setup. Re-provision from an account that can approve administrator prompts, and check that no policy or security software reverts permission changes on Windows system folders.",
  "permissionsTab.osSandboxWindowsInstallFailedHelperMissing": "The Windows sandbox helper that ships with Ave is missing, so setup could not start. Security software may have quarantined it. Reinstall Ave, then re-provision.",
  "permissionsTab.osSandboxWindowsHomePrivacyError": "Extensions are blocked by the startup AVE_HOME privacy check for {path}: {reason}.",
  "permissionsTab.homePrivacyApproveHint": "You can approve this session without isolation.",
